#requires -Version 5.1
$ErrorActionPreference='Stop'
$module=Import-Module (Join-Path $PSScriptRoot '..\src\WindowsServerMigration.psd1') -Force -PassThru -DisableNameChecking
Add-Type -TypeDefinition @'
public class WsmHttpFixtureStream : System.IO.MemoryStream {
    public WsmHttpFixtureStream(byte[] data) : base(data) {}
    public WsmHttpFixtureStream() : base() {}
    public bool Slow; public override int ReadByte() { if(Slow) System.Threading.Thread.Sleep(8); return base.ReadByte(); }
    public override bool CanTimeout { get { return true; } }
    public override int ReadTimeout { get; set; }
    public override int WriteTimeout { get; set; }
}
'@
& $module {
    $script:httpChecks=0
    function Check([bool]$Condition,[string]$Message){if(-not $Condition){throw $Message};$script:httpChecks++}
    function Reject([scriptblock]$Action,[string]$Message){$failed=$false;try{& $Action | Out-Null}catch{$failed=$true};Check $failed $Message}
    function Client([string]$Text){$stream=New-Object WsmHttpFixtureStream -ArgumentList (,[Text.Encoding]::UTF8.GetBytes($Text));$client=[pscustomobject]@{Stream=$stream};$client|Add-Member ScriptMethod GetStream {$this.Stream};$client}
    $request=Read-WsmLocalHttpRequest (Client "POST /api/operations HTTP/1.1`r`nHost: 127.0.0.1:1234`r`nContent-Length: 2`r`n`r`n{}")
    Check ($request.Method -ceq 'POST' -and $request.Body -ceq '{}' -and $request.Headers.host -ceq '127.0.0.1:1234') 'Native HTTP request parsing lost exact body or headers.'
    foreach($header in @(('Host: a'+"`r`n"+'Host: b'),'Transfer-Encoding: chunked','Content-Length: 1048577','Content-Length: -1','bad header')){Reject {Read-WsmLocalHttpRequest (Client ("GET / HTTP/1.1`r`n"+$header+"`r`n`r`n"))} 'Malformed HTTP input was accepted.'}
    Reject {Read-WsmLocalHttpRequest (Client "PUT / HTTP/1.1`r`n`r`n")} 'Unsupported HTTP verb was accepted.'
    Reject {Read-WsmLocalHttpRequest (Client "POST / HTTP/1.1`r`nContent-Length: 3`r`n`r`nx")} 'Truncated HTTP body was accepted.'
    Reject {Read-WsmLocalHttpRequest (Client ("GET / HTTP/1.1`r`nX: "+('a'*8192)+"`r`n`r`n"))} 'Oversized headers were accepted.'
    $slow=Client "GET / HTTP/1.1`r`n`r`n";$slow.Stream.Slow=$true;Reject {Read-WsmLocalHttpRequest $slow -MaximumRequestMilliseconds 10} 'Slow-trickle request exceeded the aggregate deadline without rejection.'
    $client=[pscustomobject]@{Stream=(New-Object WsmHttpFixtureStream)};$client|Add-Member ScriptMethod GetStream {$this.Stream}
    $body=[Text.Encoding]::UTF8.GetBytes(('完整內容'*5000));Write-WsmLocalHttpResponse $client 200 'text/html; charset=utf-8' $body
    $actual=$client.Stream.ToArray();$text=[Text.Encoding]::UTF8.GetString($actual);$boundary=$text.IndexOf("`r`n`r`n");$header=$text.Substring(0,$boundary)
    Check ($header.Contains('Content-Length: '+$body.Length) -and $text.Substring($boundary+4) -ceq [Text.Encoding]::UTF8.GetString($body)) 'Native response writer truncated UTF-8 content or used character length.'
    Check ($header.Contains("script-src 'self'") -and -not $header.Contains('unsafe-inline') -and -not $header.Contains('adguard')) 'Native security headers differ from the declared policy.'
    $documentRoot=Join-Path ([IO.Path]::GetTempPath()) ('wsm-html-docs-'+[Guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory((Join-Path $documentRoot 'html'))
    try{
        $planPath=Join-Path (Join-Path $documentRoot 'html') 'MIGRATION-4-PLAN.html';$emptyPlanPath=Join-Path (Join-Path $documentRoot 'html') 'MIGRATION--PLAN.html';$manualPath=Join-Path (Join-Path $documentRoot 'html') 'operations.html';[IO.File]::WriteAllText($planPath,'plan');[IO.File]::WriteAllText($emptyPlanPath,'empty plan');[IO.File]::WriteAllText($manualPath,'manual')
        $documentRoutes=Get-WsmHtmlDocuments $documentRoot
        Check (-not $documentRoutes.ContainsKey('/docs/html/MIGRATION-4-PLAN.html') -and -not $documentRoutes.ContainsKey('/html/MIGRATION-4-PLAN.html') -and -not $documentRoutes.ContainsKey('/docs/html/MIGRATION--PLAN.html') -and $documentRoutes['/docs/html/operations.html'] -ceq $manualPath -and [IO.File]::Exists($planPath) -and [IO.File]::Exists($emptyPlanPath)) 'PLAN HTML remained routable or filtering removed/changed an ordinary document.'
    }finally{Remove-Item -LiteralPath $documentRoot -Recurse -Force}
    $overviewCatalog=[pscustomobject]@{PairId='pair-fixture';Items=@([pscustomobject]@{ItemId='one';Name='One';Decision='Include';Status='Discovered';MigrationSpec=[pscustomobject]@{TransferChannel='C';Adapter='FileScope'}},[pscustomobject]@{ItemId='two';Name='Two';Decision='Pending';Status='Discovered';MigrationSpec=[pscustomobject]@{TransferChannel='NonC';Adapter='ManualWorkflow'}});Approval=$null;Assistive=[pscustomobject]@{Selections=[pscustomobject]@{Revision=1;Items=@([pscustomobject]@{ItemId='one';Selected=$true;Reason='included for test'},[pscustomobject]@{ItemId='two';Selected=$true;Reason='pending for test'})};SourceSnapshot=@{SHA256='a'*64};TargetCurrent=$null;Comparison=[pscustomobject]@{ManualPreparation=@([pscustomobject]@{SoftwareId='sw-fixture';Status='AccountScopeReviewRequired'})}}}
    $overviewStage=[pscustomobject]@{Latest=[pscustomobject]@{PayloadGeneration=3;Stage='Restore';Status='FutureStatus';Assistive=[pscustomobject]@{ItemResults=@([pscustomobject]@{ItemId='one';Pending=$false;Deferred=$false;Status='VerifiedNo'});FileResults=@([pscustomobject]@{ItemId='one';Channel='C';RelativePath='a.txt';OriginalPath='C:\\a.txt';PreservedPath='C:\\b.txt';EffectivePath='C:\\b.txt';Status='BlockedConflict';ExistingTargetPath='';ExistingTargetHash='';SourceHash='';ObservedHash='';Reason='conflict';EntryId='e';Generation=3;ProjectedGeneration=3})}}}
    $overview=Get-WsmHtmlOverviewProjection $overviewCatalog $overviewStage @{one=$true;two=$true} 'Manager' 7
    Check ($overview.provenance.pairId -ceq 'pair-fixture' -and $overview.provenance.revision -eq 7 -and $overview.provenance.generation -eq 3 -and $overview.provenance.stage -ceq 'Restore' -and $overview.provenance.stageStatus -ceq 'FutureStatus') 'Overview omitted producer provenance or changed the producer stage status.'
    $selectionItems=@([pscustomobject]@{ItemId='source-approved';Name='Source approved';Category='App';NaturalKey='one';Decision='Include';Dependencies=@()},[pscustomobject]@{ItemId='source-unselected';Name='Not source selected';Category='App';NaturalKey='two';Decision='Include';Dependencies=@()},[pscustomobject]@{ItemId='not-included';Name='Not included';Category='App';NaturalKey='three';Decision='Pending';Dependencies=@()})
    $sealedInventoryCatalog=[pscustomobject]@{Items=$selectionItems;Approval=[pscustomobject]@{Kind='MigrationPlan'};Assistive=[pscustomobject]@{Selections=[pscustomobject]@{Revision=2;Items=@([pscustomobject]@{ItemId='source-approved';Selected=$true;Reason='source reviewed'},[pscustomobject]@{ItemId='source-unselected';Selected=$false;Reason='source not selected'})}}}
    $sealedInventory=Get-WsmHtmlInventoryProjection $sealedInventoryCatalog @{ 'source-approved'=$true } @{}
    Check (@($sealedInventory.items|Where-Object itemId -CEQ 'source-approved')[0].selectable -and @($sealedInventory.items|Where-Object itemId -CEQ 'source-approved')[0].approvalStatus -ceq 'Approved' -and -not @($sealedInventory.items|Where-Object itemId -CEQ 'source-unselected')[0].selectable -and @($sealedInventory.items|Where-Object itemId -CEQ 'source-unselected')[0].approvalStatus -ceq 'NotInApprovedSource' -and -not @($sealedInventory.items|Where-Object itemId -CEQ 'not-included')[0].selectable) 'Sealed selection projection allowed source-unselected/Non-Include items or labeled decision Include alone as approved.'
    $unsealedInventoryCatalog=[pscustomobject]@{Items=@($selectionItems[0]);Approval=[pscustomobject]@{Kind='ReviewRecord'};Assistive=$sealedInventoryCatalog.Assistive}
    $unsealedInventory=Get-WsmHtmlInventoryProjection $unsealedInventoryCatalog @{} @{}
    Check (@($unsealedInventory.items)[0].selectable -and @($unsealedInventory.items)[0].approvalStatus -ceq 'ApprovalNotSealed') 'A non-sealed approval incorrectly blocked native selection editing or was mislabeled as sealed approval.'
    Check ($overview.nextStep.action -ceq 'TargetSnapshot' -and $overview.nextStep.actionMetadata.action -ceq $overview.nextStep.action -and $overview.nextStep.actionMetadata.parameters.Count -gt 0 -and $overview.nextStep.reason) 'Overview next action was not bound to current role allowlist metadata and a rationale.'
    Check (@($overview.counts | Where-Object id -CEQ 'pending')[0].value -eq 0 -and @($overview.counts | Where-Object id -CEQ 'stageObjects')[0].value -eq 1 -and @($overview.counts | Where-Object id -CEQ 'fileConflicts')[0].value -eq 1 -and @($overview.counts | Where-Object id -CEQ 'includeSelected')[0].value -eq 1 -and @($overview.counts | Where-Object id -CEQ 'availability')[0].value -ceq '未測試' -and $overview.metrics.approved -ceq 'NotMeasured' -and $overview.metrics.executable -ceq 'NotMeasured' -and @($overview.steps|Where-Object id -CEQ 'approval')[0].status -ceq 'NotObserved') 'Overview counters treated Include selection as sealed approval or fabricated a denominator, executable count, or availability result.'
    Check (@($overview.counts|Where-Object id -CEQ 'cItems')[0].value -eq 1 -and @($overview.counts|Where-Object id -CEQ 'noncItems')[0].value -eq 1 -and @($overview.counts|Where-Object id -CEQ 'cStageItems')[0].value -eq 1 -and @($overview.counts|Where-Object id -CEQ 'noncStageItems')[0].value -eq 0 -and @($overview.counts|Where-Object id -CEQ 'noncManualWorkflowSelected')[0].value -eq 1 -and @($overview.counts|Where-Object id -CEQ 'softwarePreparationRows')[0].value -eq 1 -and @($overview.counts|Where-Object id -CEQ 'cPlacedFiles')[0].value -eq 0 -and @($overview.steps|Where-Object id -CEQ 'softwarePreparation')[0].status -ceq 'ReviewRequired') 'Producer-backed C/NonC, software preparation, manual selection, or effective-path counts lost their units or distinct meanings.'
    $unknownOverview=Get-WsmHtmlOverviewProjection $overviewCatalog ([pscustomobject]@{Latest=$null}) @{one=$true} 'Manager' 8
    Check (@($unknownOverview.counts | Where-Object id -CEQ 'stageObjects')[0].status -ceq 'Unknown' -and @($unknownOverview.counts | Where-Object id -CEQ 'pending')[0].value -ceq 'Unknown' -and $unknownOverview.workloadStatus -ceq 'NotObserved') 'Missing stage evidence was represented as a measured zero or success.'
    $unassistedCatalog=[pscustomobject]@{PairId='pair-unassisted';Items=@([pscustomobject]@{ItemId='unassisted-item';Name='Unassisted';Decision='Pending';Status='Discovered'});Approval=$null}
    $unassistedOverview=Get-WsmHtmlOverviewProjection $unassistedCatalog ([pscustomobject]@{Latest=$null;AllCurrent=@()}) @{} 'Manager' 0
    Check ($unassistedOverview.stateNextAction.action -ceq 'AssistiveEnable' -and @($unassistedOverview.counts|Where-Object id -CEQ 'selected')[0].value -ceq 'Unknown' -and $unassistedOverview.workloadStatus -ceq 'NotObserved') 'An unassisted pair was rendered as empty/success instead of directing to the existing enable action with unknown selection.'
    $emptyWorkspace=Join-Path ([IO.Path]::GetTempPath()) ('wsm-html-empty-'+[Guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($emptyWorkspace)
    try{
        Initialize-WsmWorkspace $emptyWorkspace | Out-Null
        $emptyView=Get-WsmHtmlViewSnapshot $emptyWorkspace '' 'overview' 'Manager' 'session-fixture' 'context-empty' ''
        Check (-not $emptyView.assistiveEnabled -and -not $emptyView.canSaveSelection -and -not $emptyView.viewContext.pairId -and $emptyView.stateNextAction.action -ceq 'Initialize' -and $emptyView.counts[0].value -ceq 'Unknown') ('The no-pair HTTP view omitted explicit disabled capabilities or the role-appropriate first action: '+($emptyView|ConvertTo-Json -Compress -Depth 8))
        $fixtureHost=[pscustomobject]@{HostId=[Guid]::NewGuid().ToString();Fingerprint=('d'*64);Name='empty-state-fixture'}
        $fixtureItem=New-WsmItem $fixtureHost.HostId Runtime App 'Empty-state item' 'empty-state' @{}
        $fixtureInventory=New-WsmInventory $fixtureHost 1 @($fixtureItem);$fixturePath=Join-Path $emptyWorkspace 'empty-state-inventory.json';Write-WsmJson $fixturePath $fixtureInventory
        $fixtureCatalog=Import-WsmInventory $emptyWorkspace $fixturePath (Get-FileHash -LiteralPath $fixturePath -Algorithm SHA256).Hash 'empty-state-target'
        $unassistedView=Get-WsmHtmlViewSnapshot $emptyWorkspace $fixtureCatalog.PairId 'overview' 'Manager' 'session-fixture' 'context-unassisted' ''
        Check (-not $unassistedView.assistiveEnabled -and -not $unassistedView.canSaveSelection -and $unassistedView.stateNextAction.action -ceq 'AssistiveEnable' -and @($unassistedView.counts|Where-Object id -CEQ 'selected')[0].value -ceq 'Unknown') 'The unassisted pair HTTP view omitted its current state or enabled an unavailable selection save.'
    }finally{if([IO.Directory]::Exists($emptyWorkspace)){Remove-Item -LiteralPath $emptyWorkspace -Recurse -Force}}
    $stageSet=@(
        [pscustomobject]@{Stage='Cutover';Status='Succeeded';ProducedUtc='2026-10-10T00:00:00Z';PayloadGeneration=3},
        [pscustomobject]@{Stage='PostCutoverValidation';Status='Succeeded';ProducedUtc='2026-10-09T00:01:00Z';PayloadGeneration=2}
    )
    $overviewStage=[pscustomobject]@{Latest=$overviewStage.Latest;AllCurrent=$stageSet};$overviewStage.Latest.Status='Partial';$overviewStage.Latest.Assistive.ItemResults=@(
        [pscustomobject]@{ItemId='deferred';Pending=$false;Deferred=$false;Status='DeferredManual'},
        [pscustomobject]@{ItemId='conflict';Pending=$false;Deferred=$false;Status='BlockedConflict'},
        [pscustomobject]@{ItemId='pending';Pending=$true;Deferred=$false;Status='ReviewRequired'}
    );$overviewStage.Latest.Assistive.FileResults=@([pscustomobject]@{ItemId='one';Channel='C';RelativePath='a.txt';OriginalPath='C:\\a.txt';PreservedPath='C:\\b.txt';EffectivePath='C:\\b.txt';Status='BlockedConflict';ExistingTargetPath='';ExistingTargetHash='';SourceHash='';ObservedHash='';Reason='conflict';EntryId='e';Generation=3;ProjectedGeneration=3})
    $stageOverview=Get-WsmHtmlOverviewProjection $overviewCatalog $overviewStage @{one=$true} 'Manager' 9
    Check (@($stageOverview.counts|Where-Object id -CEQ 'failedItems')[0].value -eq 1 -and @($stageOverview.counts|Where-Object id -CEQ 'deferred')[0].value -eq 1 -and @($stageOverview.counts|Where-Object id -CEQ 'pending')[0].value -eq 2) 'DeferredManual was counted as a failure or distinct pending/deferred item counts were wrong.'
    Check (@($stageOverview.steps|Where-Object id -CEQ 'activation')[0].resultStatus -ceq 'Succeeded' -and @($stageOverview.steps|Where-Object id -CEQ 'postCutoverValidation')[0].status -ceq 'NotObserved' -and @($stageOverview.steps|Where-Object id -CEQ 'businessAcceptance')[0].status -ceq 'NotObserved' -and @($stageOverview.steps|Where-Object id -CEQ 'delivery')[0].status -ceq 'NotObserved') 'Cutover activation or a prior-generation acceptance was confused with current business acceptance, or delivery evidence was fabricated.'
    $acceptedStage=[pscustomobject]@{Stage='PostCutoverValidation';Status='Succeeded';ProducedUtc='2026-10-10T00:02:00Z';PayloadGeneration=3;Sequence=2;Assistive=[pscustomobject]@{ItemResults=@();FileResults=@()}};$acceptedCatalog=ConvertFrom-WsmJson ($overviewCatalog|ConvertTo-Json -Depth 100);$acceptedCatalog.Assistive.TargetCurrent=@{HostId='target'};$acceptedCatalog.Assistive.Comparison=[pscustomobject]@{ManualPreparation=@()};$acceptedCatalog.Approval=[pscustomobject]@{Kind='MigrationPlan';Hash=('a'*64)};$acceptedOverview=Get-WsmHtmlOverviewProjection $acceptedCatalog ([pscustomobject]@{Latest=$acceptedStage;AllCurrent=@($acceptedStage)}) @{one=$true} 'Manager' 10
    Check (@($acceptedOverview.steps|Where-Object id -CEQ 'postCutoverValidation')[0].resultStatus -ceq 'Succeeded' -and @($acceptedOverview.steps|Where-Object id -CEQ 'businessAcceptance')[0].status -ceq 'Accepted' -and $acceptedOverview.nextStep.action -eq $null -and $acceptedOverview.nextStep.reason -match '切換後驗證已成功') 'A successful current-generation post-cutover validation was not distinguished from activation or lacked phase-accurate Chinese guidance.'
    $approvalPending=ConvertFrom-WsmJson ($acceptedCatalog|ConvertTo-Json -Depth 100);$approvalPending.Approval=$null;$noStage=[pscustomobject]@{Latest=$null;AllCurrent=@()};$noApprovalOverview=Get-WsmHtmlOverviewProjection $approvalPending $noStage @{one=$true} 'Manager' 12;$noApprovalSource=Get-WsmHtmlOverviewProjection $approvalPending $noStage @{one=$true} 'Source' 12
    Check ($noApprovalOverview.nextStep.action -ceq 'ApproveMigration' -and $noApprovalOverview.nextStep.reason -match 'Include 選取本身不代表核准' -and $noApprovalSource.nextStep.action -eq $null -and $noApprovalSource.nextStep.reason -match 'Manager') 'An otherwise ready unapproved plan lacked a Manager-only core approval next step and explicit role restriction.'
    $approvedNoStage=Get-WsmHtmlOverviewProjection $acceptedCatalog $noStage @{one=$true} 'Target' 13
    Check ($approvedNoStage.nextStep.action -ceq 'RestorePreview' -and $approvedNoStage.nextStep.reason -match '原生還原預覽') 'An approved plan without stage evidence lacked safe role-appropriate preview guidance.'
    foreach($statusFixture in @(@('Cancelled','已取消'),@('Interrupted','曾中斷'))){$phase=[pscustomobject]@{Stage='Restore';Status=$statusFixture[0];ProducedUtc='2026-10-10T00:03:00Z';PayloadGeneration=4;Assistive=[pscustomobject]@{ItemResults=@();FileResults=@()}};$phaseOverview=Get-WsmHtmlOverviewProjection $acceptedCatalog ([pscustomobject]@{Latest=$phase;AllCurrent=@($phase)}) @{one=$true} 'Manager' 11;Check ($phaseOverview.nextStep.action -ceq 'AssistiveReport' -and $phaseOverview.nextStep.reason -match $statusFixture[1]) 'Cancelled/interrupted phase evidence lacked an actionable, status-specific recovery next step.'}
    $channelCatalog=[pscustomobject]@{PairId='pair-channels';DecisionRevision=5;Approval=$null;Source=[pscustomobject]@{HostId='source'};Target=[pscustomobject]@{HostId='target'};Items=@(
        [pscustomobject]@{ItemId='c-item';Name='C item';Decision='Include';Status='Discovered';MigrationSpec=[pscustomobject]@{TransferChannel='C';Adapter='FileScope'}},
        [pscustomobject]@{ItemId='nonc-item';Name='NonC item';Decision='Include';Status='Discovered';MigrationSpec=[pscustomobject]@{TransferChannel='NonC';Adapter='FileScope'}},
        [pscustomobject]@{ItemId='manual-item';Name='Manual item';Decision='Include';Status='Discovered';MigrationSpec=[pscustomobject]@{TransferChannel='C';Adapter='ManualWorkflow'}}
    );Assistive=[pscustomobject]@{Revision=8;Selections=[pscustomobject]@{Revision=3;Items=@([pscustomobject]@{ItemId='c-item';Selected=$true},[pscustomobject]@{ItemId='nonc-item';Selected=$true},[pscustomobject]@{ItemId='manual-item';Selected=$true})};SourceSnapshot=$null;TargetCurrent=$null;Comparison=$null;FileResults=@()}}
    $fileRows=@([pscustomobject]@{ItemId='c-item';Channel='C';RelativePath='one.txt';OriginalPath='C:\\one.txt';PreservedPath='D:\\one.txt';EffectivePath='D:\\one.txt';Status='Applied';ExistingTargetPath='';ExistingTargetHash='';SourceHash='a'*64;ObservedHash='a'*64;Reason='';EntryId='c1';Generation=3;ProjectedGeneration=3},[pscustomobject]@{ItemId='nonc-item';Channel='NonC';RelativePath='two.txt';OriginalPath='C:\\two.txt';PreservedPath='\\target\\share\\two.txt';EffectivePath='';Status='DeferredManual';ExistingTargetPath='';ExistingTargetHash='';SourceHash='b'*64;ObservedHash='';Reason='manual';EntryId='nc1';Generation=3;ProjectedGeneration=3})
    $channelCatalog.Assistive.FileResults=$fileRows
    $channelStage=[pscustomobject]@{Latest=[pscustomobject]@{PayloadGeneration=3;Stage='Restore';Status='Partial';ProducedUtc='2026-10-10T00:00:00Z';Assistive=[pscustomobject]@{ItemResults=@([pscustomobject]@{ItemId='c-item';Pending=$false;Deferred=$false;Status='Applied'},[pscustomobject]@{ItemId='nonc-item';Pending=$true;Deferred=$false;Status='DeferredManual'});FileResults=$fileRows}};AllCurrent=@()}
