    $deliveryCatalog=[pscustomobject]@{PairId='pair-delivery';Items=@();Approval=[pscustomobject]@{ApprovalId='approval-fixture';Hash=('e'*64);TargetHostId='target';Kind='MigrationPlan'};Source=[pscustomobject]@{HostId='source'};Target=[pscustomobject]@{HostId='target'};Generation=3;DeliveryReceipts=@($sealedReceipt);Assistive=[pscustomobject]@{Revision=1;Selections=[pscustomobject]@{Revision=1;Items=@()}}}
    $deliveryStage=[pscustomobject]@{Latest=[pscustomobject]@{PayloadGeneration=3;Stage='Restore';Status='ReviewRequired';ProducedUtc='2026-10-10T00:00:00Z';Assistive=[pscustomobject]@{ItemResults=@();FileResults=@()}};AllCurrent=@()}
