    $vector=[pscustomobject]@{decisionRevision=7;selectionRevision=12;dataVersion=('a'*64)}
    $matchingVector=[pscustomobject]@{expectedDecisionRevision=7;expectedSelectionRevision=12;expectedDataVersion=('a'*64)}
