    Check (-not (Test-WsmHtmlExpectedVector ([pscustomobject]@{expectedDecisionRevision=8;expectedSelectionRevision=12;expectedDataVersion=('a'*64)}) $vector) -and -not (Test-WsmHtmlExpectedVector ([pscustomobject]@{expectedDecisionRevision=7;expectedSelectionRevision=13;expectedDataVersion=('a'*64)}) $vector) -and -not (Test-WsmHtmlExpectedVector ([pscustomobject]@{expectedDecisionRevision=7;expectedSelectionRevision=12;expectedDataVersion=('b'*64)}) $vector)) 'A decision-only, selection-only, or catalog-data-only freshness mismatch was accepted.'
