    $actions=@(Get-WsmHtmlActionMetadata Manager)
    $selectionAction=@($actions|Where-Object action -CEQ SaveSelection)[0];$restoreAction=@($actions|Where-Object action -CEQ SetRestoreChoice)[0];$softwareAction=@($actions|Where-Object action -CEQ SetSoftwareVersion)[0]
    Check ($selectionAction.requiredRole -ceq 'Manager' -and $selectionAction.roleAvailable -and @($selectionAction.parameters|Where-Object name -in @('ExpectedDecisionRevision','ExpectedSelectionRevision','ExpectedDataVersion')).Count -eq 0 -and @($restoreAction.parameters|Where-Object name -in @('ExpectedDecisionRevision','ExpectedSelectionRevision','ExpectedDataVersion')).Count -eq 0 -and @($softwareAction.parameters|Where-Object name -CEQ BeforeWrite).Count -eq 0) 'Server-owned CAS/internal callback parameters were exposed in UI action metadata or lost role constraints.'
    $targetActions=@(Get-WsmHtmlActionMetadata Target);$sourceActions=@(Get-WsmHtmlActionMetadata Source)
    $managerTargetSnapshot=@($actions|Where-Object action -CEQ TargetSnapshot)[0];$managerImportInventory=@($actions|Where-Object action -CEQ ImportInventory)[0];$targetTargetSnapshot=@($targetActions|Where-Object action -CEQ TargetSnapshot)[0];$targetImportInventory=@($targetActions|Where-Object action -CEQ ImportInventory)[0]
    $sourceInventory=@($sourceActions|Where-Object action -CEQ Inventory)[0];$managerInventory=@($actions|Where-Object action -CEQ Inventory)[0];$targetInventory=@($targetActions|Where-Object action -CEQ Inventory)[0];$sourceEnrolledInventory=@($sourceActions|Where-Object action -CEQ EnrolledInventory)[0];$targetMaterialJobStatus=@($targetActions|Where-Object action -CEQ MaterialJobStatus)[0];$managerMaterialJobStatus=@($actions|Where-Object action -CEQ MaterialJobStatus)[0];$sourcePeerProof=@($sourceActions|Where-Object action -CEQ NonCPeerProof)[0];$managerNonCPlan=@($actions|Where-Object action -CEQ NonCPlan)[0]
    Check ($managerTargetSnapshot.requiredRole -ceq 'Manager' -and $managerTargetSnapshot.roleAvailable -and $managerImportInventory.requiredRole -ceq 'Manager' -and $managerImportInventory.roleAvailable -and -not $targetTargetSnapshot.roleAvailable -and -not $targetImportInventory.roleAvailable -and $sourceEnrolledInventory.requiredRole -ceq 'Source' -and $sourceEnrolledInventory.roleAvailable -and $targetMaterialJobStatus.requiredRole -ceq 'Target' -and $targetMaterialJobStatus.roleAvailable -and -not $managerMaterialJobStatus.roleAvailable -and $sourcePeerProof.requiredRole -ceq 'Source' -and $sourcePeerProof.roleAvailable -and $managerNonCPlan.requiredRole -ceq 'Manager' -and $managerNonCPlan.roleAvailable) 'Action metadata role groups diverged from the actual enrolled-inventory, target-snapshot, material-job-status, peer-proof, import, or Non-C plan consumer.'
    Check ($sourceInventory.requiredRole -ceq 'Source' -and $sourceInventory.supportedRoles -contains 'Source' -and $sourceInventory.roleAvailable -and $targetInventory.requiredRole -ceq 'Source' -and $targetInventory.supportedRoles -contains 'Target' -and $targetInventory.roleAvailable -and $managerInventory.requiredRole -ceq 'Source' -and -not $managerInventory.roleAvailable -and @($targetInventory.parameters|Where-Object {$_.name -ceq 'OutputDirectory' -and $_.type -ceq 'path'}).Count -eq 1) 'Local Inventory metadata must retain Source grouping, support the Source and Target host roles, and remain unavailable to Manager.'
    Reject {ConvertTo-WsmHtmlArguments (Get-Command Set-WsmAssistiveSoftwareVersion) ([pscustomobject]@{BeforeWrite='injected'})} 'HTML operation arguments accepted the internal server callback.'
    $submit=@($actions | Where-Object action -CEQ WindowsSettingsSubmit)[0]
    Check (@($submit.parameters | Where-Object name -CEQ ExpectedRevision).Count -eq 1 -and @($submit.parameters | Where-Object name -CEQ Decisions)[0].allowEmpty) 'Settings preview revision or legitimate empty decisions are hidden by native metadata.'
    $hash1=Get-WsmHtmlRequestHash 'C:\fixture' 'pair-one' 'Manager' 'CheckToolRelease' ([pscustomobject]@{Path='C:\release'}) 0
    $hash2=Get-WsmHtmlRequestHash 'C:\fixture' 'pair-two' 'Manager' 'CheckToolRelease' ([pscustomobject]@{Path='C:\release'}) 0
    $hashVectorA=Get-WsmHtmlRequestHash 'C:\fixture' 'pair-one' 'Manager' 'CheckToolRelease' ([pscustomobject]@{Path='C:\release'}) 0 7 12 ('a'*64)
    $hashVectorB=Get-WsmHtmlRequestHash 'C:\fixture' 'pair-one' 'Manager' 'CheckToolRelease' ([pscustomobject]@{Path='C:\release'}) 0 7 12 ('b'*64)
    Check ($hash1 -cne $hash2 -and $hash1 -ceq (Get-WsmHtmlRequestHash 'C:\fixture' 'pair-one' 'Manager' 'CheckToolRelease' ([pscustomobject]@{Path='C:\release'}) 0) -and $hashVectorA -cne $hashVectorB) 'Durable idempotency hash lost pair/vector scope or cannot survive reconnection.'
    $legacyBody=ConvertFrom-WsmJson '{"args":{"Path":"C:\\release"},"expectedRevision":0}'
    $legacyHash=& {Set-StrictMode -Version Latest;Get-WsmHtmlRequestHashForBody 'C:\fixture' 'pair-one' 'Manager' 'CheckToolRelease' $legacyBody}
    $legacyExpectedHash=Get-WsmHtmlRequestHash 'C:\fixture' 'pair-one' 'Manager' 'CheckToolRelease' $legacyBody.args 0 $null $null $null
    Check ($legacyHash -ceq $legacyExpectedHash -and -not $legacyBody.PSObject.Properties['expectedDecisionRevision'] -and -not $legacyBody.PSObject.Properties['expectedSelectionRevision'] -and -not $legacyBody.PSObject.Properties['expectedDataVersion']) 'A legacy operation body with only required CAS fields failed hashing under strict mode or gained a different idempotency hash.'
    Check ($actions.Count -gt 90) 'HTML actions do not expose the native operation surface.'
    Check (-not @($actions | Where-Object {$_.parameters | Where-Object name -EQ CancellationToken}).Count) 'Cancellation capability was exposed as editable input.'
    $probe=Get-Command Export-WsmAssistiveHttpProbe
    Check (-not @($actions | Where-Object {$_.parameters | Where-Object name -EQ RequestAdapter}).Count) 'Internal probe script adapter appeared in browser forms.'
    Reject {ConvertTo-WsmHtmlArguments $probe ([pscustomobject]@{Origin='http://127.0.0.1:1234';OutputPath='C:\fixture.json';RequestAdapter='throw injected'})} 'Internal script adapter accepted through HTML.'
    $command=Get-Command Set-WsmAssistiveSoftwareVersion
    $args=ConvertTo-WsmHtmlArguments $command ([pscustomobject]@{Workspace='C:\fixture';PairId=[Guid]::NewGuid().ToString();SoftwareId=('a'*64);ChosenVersion='new; $(invalid)';Reason='owner selected';ExpectedRevision=1})
    Check ($args.ChosenVersion -ceq 'new; $(invalid)' -and $args.Reason -ceq 'owner selected' -and $args.ExpectedRevision -eq 1) 'Typed arguments interpreted source text as commands.'
    Reject {ConvertTo-WsmHtmlArguments $command ([pscustomobject]@{Unknown='anything'})} 'Unknown action arguments were accepted.'
    $outputs=@(Get-WsmHtmlResultProjection @([pscustomobject]@{Status='ReviewRequired';Path='C:\report.html';Secrets='sentinel';Password='sentinel';Xml='<secret/>'}))
    Check ($outputs.Count -eq 1 -and $outputs[0].Status -ceq 'ReviewRequired' -and ($outputs|ConvertTo-Json) -notmatch 'sentinel|<secret') 'Durable job outputs included configuration or secrets.'
    $safeError=Get-WsmHtmlSafeError 'Access to the path C:\secret\sentinel.json was denied.'
    Check ($safeError.code -ceq 'permission_denied' -and $safeError.correlationId -and $safeError.nextStep -and ($safeError|ConvertTo-Json -Compress) -notmatch 'sentinel|secret.json') 'Actionable permission errors leaked an exception path or omitted their safe recovery details.'
    $workerFailureError=Get-WsmHtmlSafeError 'WorkerReportedFailure';Check ($workerFailureError.code -ceq 'operation_failed' -and $workerFailureError.correlationId -and $workerFailureError.nextStep -and ($workerFailureError|ConvertTo-Json -Compress) -notmatch 'WorkerReportedFailure') 'A worker-reported Failed result could not be surfaced with safe durable recovery guidance.'
    Check ((Get-WsmHtmlSafeError 'RejectedToken').code -ceq 'invalid_token' -and (Get-WsmHtmlSafeError 'RejectedOrigin').code -ceq 'rejected_origin' -and (Get-WsmHtmlSafeError 'RejectedHost').code -ceq 'rejected_host') 'Authentication, origin, and host failures did not remain separately actionable.'
    $reportError=Get-WsmHtmlSafeError 'ReportUnavailable: no details';Check ($reportError.code -ceq 'report_unavailable' -and $reportError.nextStep -and ($reportError|ConvertTo-Json -Compress) -notmatch 'no details') 'Unavailable report errors lacked a safe actionable code.'
    $recoveryError=Get-WsmHtmlSafeError 'Interrupted workspace transaction requires repair.';Check ($recoveryError.code -ceq 'workspace_recovery_required' -and $recoveryError.nextStep -and ($recoveryError|ConvertTo-Json -Compress) -notmatch 'Interrupted workspace transaction') 'Workspace recovery errors did not expose safe actionable repair guidance.'
    $savedReplay=Get-WsmHtmlReplayResponse ([pscustomobject]@{jobId='saved-operation';action='SaveSelection';status='Succeeded';revision=12})
    Check ($savedReplay.jobId -ceq 'saved-operation' -and $savedReplay.status -ceq 'Saved' -and $savedReplay.revision -eq 12 -and $savedReplay.Count -eq 3) 'Quick-save replay changed the stable operation result shape.'
    $historyRoot=Join-Path ([IO.Path]::GetTempPath()) ('wsm-http-history-'+[Guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($historyRoot)
    try{
        $reportPath=Join-Path $historyRoot 'material-job.html';[IO.File]::WriteAllText($reportPath,'<!doctype html><title>Material status</title>')
        $reportResult=[pscustomobject]@{HtmlPath=$reportPath;Status='ReportOnly';LockStatus='Locked';Secret='not-public'}
        $projected=@(Get-WsmHtmlResultProjection @($reportResult));$artifacts=@(Get-WsmHtmlReportArtifacts 'MaterialJobStatus' $projected)
        Check ($artifacts.Count -eq 1 -and $artifacts[0].Path -ceq $reportPath -and $artifacts[0].SHA256 -ceq (Get-FileHash $reportPath -Algorithm SHA256).Hash.ToLowerInvariant() -and (Get-WsmOperationStatusCode $projected) -eq 0 -and ($projected|ConvertTo-Json) -notmatch 'not-public') 'Material job status report could not cross the safe job projection and authenticated HTML artifact route as a completed read-only operation.'
        $id=[Guid]::NewGuid().ToString();$key=[Guid]::NewGuid().ToString();$recordPath=Join-Path $historyRoot ($id+'.json')
        Write-WsmJson $recordPath ([pscustomobject]@{jobId=$id;idempotencyKey=$key;RequestHash=('a'*64);status='Running';canCancel=$true})
        $jobs=@{};$keys=@{};Import-WsmHtmlJobHistory $historyRoot $jobs $keys
        Check ($keys.ContainsKey($key) -and $keys[$key].Id -ceq $id -and $keys[$key].Hash -ceq ('a'*64)) 'Restart lost the durable idempotency binding.'
        Check ($jobs[$id].Record.status -ceq 'Interrupted' -and -not $jobs[$id].Record.canCancel -and (Read-WsmJson $recordPath).status -ceq 'Interrupted') 'Restart promoted an unfinished worker or exposed a stale cancellation handle.'
        Check ($jobs[$id].Record.pairId -eq $null -and $jobs[$id].Record.role -eq $null -and $jobs[$id].Record.startedRevision -eq $null) 'Legacy job history was backfilled with current or inferred provenance.'
        $errorRoot=Join-Path $historyRoot 'console-errors';[void][IO.Directory]::CreateDirectory($errorRoot);$safeError=New-WsmHtmlError 'The request could not be used.' 'invalid_request' 'Review the current page.';Write-WsmHtmlErrorRecord $errorRoot $safeError '/api/view' 'pair-fixture'
        $errorText=[IO.File]::ReadAllText((Join-Path $errorRoot 'errors.jsonl'))
        Check ($errorText -match [regex]::Escape($safeError.correlationId) -and $errorText -match 'invalid_request' -and $errorText -notmatch 'not-public|secret|Password|token') 'Safe error correlation was not recorded separately from jobs without capturing request data.'
    }finally{if([IO.Directory]::Exists($historyRoot)){Remove-Item -LiteralPath $historyRoot -Recurse -Force}}
    Write-Host ('PASS: '+$script:httpChecks+' native HTTP parser/writer and typed action checks; live browser transport is independently probed.')
}
